entry.content:
又到了一周了———以后文章基本会在周五更新之前搞了一个url隐形转发嘛然后在评论区lyx提醒url隐形转发有许多问题，并且指出可以用cf-workers进行反代半年前博客刚刚搞好没多久的时候我写过一篇用cf-workers镜像网站的文章，其实都是一样的然后我想起来这茬，把代码复制一看，哦豁，代码没用了，于是我匆匆忙忙去找新代码，最终如下———

直接复制下面的代码放进worker的代码里注意，cf-workers自带的worker.dev被墙了（万恶的GFW）因此，请使用自定义域名然鹅还是会有时抽风我还在想到底怎么解决
// 替换成你想镜像的站点const upstream = &#x27;www.example.com&#x27; // 如果那个站点有专门的移动适配站点，否则保持和上面一致const upstream_mobile = &#x27;www.example.com&#x27; const blocked_region = [&#x27;KP&#x27;,&#x27;RU&#x27;] const blocked_ip_address = [&#x27;0.0.0.0&#x27;, &#x27;127.0.0.1&#x27;] const replace_dict = &#123;    &#x27;$upstream&#x27;: &#x27;$custom_domain&#x27;,    &#x27;//cdn.jsdelivr.net&#x27;: &#x27;&#x27;&#125; //以下内容都不用动addEventListener(&#x27;fetch&#x27;, event =&gt; &#123;    event.respondWith(fetchAndApply(event.request));&#125;) async function fetchAndApply(request) &#123;     const region = request.headers.get(&#x27;cf-ipcountry&#x27;).toUpperCase();    const ip_address = request.headers.get(&#x27;cf-connecting-ip&#x27;);    const user_agent = request.headers.get(&#x27;user-agent&#x27;);     let response = null;    let url = new URL(request.url);    let url_host = url.host;     if (url.protocol == &#x27;http:&#x27;) &#123;        url.protocol = &#x27;https:&#x27;        response = Response.redirect(url.href);        return response;    &#125;     if (await device_status(user_agent)) &#123;        upstream_domain = upstream    &#125; else &#123;        upstream_domain = upstream_mobile    &#125;     url.host = upstream_domain;     if (blocked_region.includes(region)) &#123;        response = new Response(&#x27;Access denied: WorkersProxy is not available in your region yet.&#x27;, &#123;            status: 403        &#125;);    &#125; else if(blocked_ip_address.includes(ip_address))&#123;        response = new Response(&#x27;Access denied: Your IP address is blocked by WorkersProxy.&#x27;, &#123;            status: 403        &#125;);    &#125; else&#123;        let method = request.method;        let request_headers = request.headers;        let new_request_headers = new Headers(request_headers);         new_request_headers.set(&#x27;Host&#x27;, upstream_domain);        new_request_headers.set(&#x27;Referer&#x27;, url.href);         let original_response = await fetch(url.href, &#123;            method: method,            headers: new_request_headers        &#125;)         let original_response_clone = original_response.clone();        let original_text = null;        let response_headers = original_response.headers;        let new_response_headers = new Headers(response_headers);        let status = original_response.status;         new_response_headers.set(&#x27;access-control-allow-origin&#x27;, &#x27;*&#x27;);        new_response_headers.set(&#x27;access-control-allow-credentials&#x27;, true);        new_response_headers.delete(&#x27;content-security-policy&#x27;);        new_response_headers.delete(&#x27;content-security-policy-report-only&#x27;);        new_response_headers.delete(&#x27;clear-site-data&#x27;);         const content_type = new_response_headers.get(&#x27;content-type&#x27;);        if (content_type.includes(&#x27;text/html&#x27;) &amp;&amp; content_type.includes(&#x27;UTF-8&#x27;)) &#123;            original_text = await replace_response_text(original_response_clone, upstream_domain, url_host);        &#125; else &#123;            original_text = original_response_clone.body        &#125;         response = new Response(original_text, &#123;            status,            headers: new_response_headers        &#125;)    &#125;    return response;&#125; async function replace_response_text(response, upstream_domain, host_name) &#123;    let text = await response.text()     var i, j;    for (i in replace_dict) &#123;        j = replace_dict[i]        if (i == &#x27;$upstream&#x27;) &#123;            i = upstream_domain        &#125; else if (i == &#x27;$custom_domain&#x27;) &#123;            i = host_name        &#125;         if (j == &#x27;$upstream&#x27;) &#123;            j = upstream_domain        &#125; else if (j == &#x27;$custom_domain&#x27;) &#123;            j = host_name        &#125;         let re = new RegExp(i, &#x27;g&#x27;)        text = text.replace(re, j);    &#125;    return text;&#125; async function device_status (user_agent_info) &#123;    var agents = [&quot;Android&quot;, &quot;iPhone&quot;, &quot;SymbianOS&quot;, &quot;Windows Phone&quot;, &quot;iPad&quot;, &quot;iPod&quot;];    var flag = true;    for (var v = 0; v &lt; agents.length; v++) &#123;        if (user_agent_info.indexOf(agents[v]) &gt; 0) &#123;            flag = false;            break;        &#125;    &#125;    return flag;&#125;

CF-Worker-Dir是一款适用于Cloudflare Worker平台上的云函数程序，可以使用它在一分钟内搭建属于自己的导航页面。CF-Worker-Dir提供丰富的自定义配置，同时它还可以预留了接口帮助你售出自己域名。接下来，我们会用cloudflare worker来免费创建这个小玩意。


系统安装在 Cloudflare Worker 管理页面创建一个新的 Worker 。在Worker编辑页面左边粘贴以下的代码。根据自身需要修改 config 的配置内容
/** *  自定义网站配置  */const config = &#123;  title: &quot;自定义导航&quot;,                 //write your website title  subtitle: &quot;Cloudflare Workers Dir&quot;, //write your website subtitle  logo_icon: &quot;sitemap&quot;,               //select your logo by semantic-ui icon (you can get more msg in:https://semantic-ui.com/elements/icon.html)  hitokoto: true,                     //use hitokoto or not  search:true,                        //enable search function  search_engine:[                     //choose search engine which you use    &#123;      name:&quot;百 度&quot;,      template:&quot;https://www.baidu.com/s?wd=$s&quot;    &#125;,    &#123;      name:&quot;谷 歌&quot;,      template:&quot;https://www.google.com/search?q=$s&quot;    &#125;,    &#123;      name:&quot;必 应&quot;,      template:&quot;https://www.bing.com/search?q=$s&quot;    &#125;,    &#123;      name:&quot;搜 狗&quot;,      template:&quot;https://www.sogou.com/web?query=$s&quot;    &#125;  ],  selling_ads: true,                  //Selling your domain or not.(turning on may be helpful for selling this domain by showing some ads.)  sell_info:&#123;    domain:&quot;example.com&quot;,    price:500,                        //domain price    mon_unit:&quot;yen sign&quot;,              //monetary unit     contact:[                         //how to contact you      &#123;        type:&quot;envelope&quot;,               //contact type (&quot;weixin&quot;,&quot;qq&quot;,&quot;telegram plane&quot;,&quot;envelope&quot; or &quot;phone&quot;)        content:&quot;info@example.com&quot;      &#125;    ]                          &#125;,  lists: [                            //Url list    &#123;      name:&quot;技术&quot;,      icon:&quot;code&quot;,      list:[        &#123;          url:&quot;https://oschina.net/&quot;,          name:&quot;开源中国&quot;,          desc:&quot;程序员集散地&quot;        &#125;,        &#123;          url:&quot;https://v2ex.com&quot;,          name:&quot;V2EX&quot;,          desc:&quot;程序员集散地&quot;        &#125;,        &#123;          url:&quot;https://csdn.net/&quot;,          name:&quot;CSDN技术社区&quot;,          desc:&quot;程序员集散地&quot;        &#125;,        &#123;          url:&quot;https://github.com/&quot;,          name:&quot;Github&quot;,          desc:&quot;程序员集散地&quot;        &#125;,      ]    &#125;,    &#123;      name:&quot;学习&quot;,      icon:&quot;graduation cap&quot;,      list:[        &#123;          url:&quot;https://w3school.com.cn/&quot;,          name:&quot;W3school在线教程&quot;,          desc:&quot;程序员集散地&quot;        &#125;,        &#123;          url:&quot;https://runoob.com/&quot;,          name:&quot;菜鸟教程&quot;,          desc:&quot;程序员集散地&quot;        &#125;,        &#123;          url:&quot;https://segmentfault.com/&quot;,          name:&quot;思否社区&quot;,          desc:&quot;程序员集散地&quot;        &#125;,        &#123;          url:&quot;https://jianshu.com/&quot;,          name:&quot;简书&quot;,          desc:&quot;程序员集散地&quot;        &#125;,      ]    &#125;  ]&#125;const el = (tag, attrs, content) =&gt; `&lt;$&#123;tag&#125; $&#123;attrs.join(&quot; &quot;)&#125;&gt;$&#123;content&#125;&lt;/$&#123;tag&#125;&gt;`;async function handleRequest(request) &#123;  const init = &#123;    headers: &#123;      &#x27;content-type&#x27;: &#x27;text/html;charset=UTF-8&#x27;,    &#125;,  &#125;  return new Response(renderHTML(renderIndex(),config.selling_ads? renderSeller() :null), init);&#125;addEventListener(&#x27;fetch&#x27;, event =&gt; &#123;  return event.respondWith(handleRequest(event.request))&#125;)/*通过分析链接 实时获取favicon* @url 需要分析的Url地址*/function getFavicon(url)&#123;  if(url.match(/https&#123;0,1&#125;:\/\//))&#123;    //return &quot;https://ui-avatars.com/api/?bold=true&amp;size=36&amp;background=0D8ABC&amp;color=fff&amp;rounded=true&amp;name=&quot; + url.split(&#x27;//&#x27;)[1];    return &quot;https://www.google.cn/s2/favicons?sz=64&amp;domain_url=&quot; + url;  &#125;else&#123;    //return &quot;https://ui-avatars.com/api/?bold=true&amp;size=36&amp;background=0D8ABC&amp;color=fff&amp;rounded=true&amp;name=&quot; + url;    return &quot;https://www.google.cn/s2/favicons?sz=64&amp;domain_url=http://&quot; + url;  &#125; &#125;/** Render Functions *  渲染模块函数 */function renderIndex()&#123;  const footer = el(&#x27;footer&#x27;,[],el(&#x27;div&#x27;,[&#x27;class=&quot;footer&quot;&#x27;],&#x27;Powered by&#x27; + el(&#x27;a&#x27;,[&#x27;class=&quot;ui label&quot;&#x27;,&#x27;href=&quot;https://github.com/sleepwood/cf-worker-dir&quot;&#x27;,&#x27;target=&quot;_blank&quot;&#x27;],el(&#x27;i&#x27;,[&#x27;class=&quot;github icon&quot;&#x27;],&quot;&quot;) + &#x27;Cf-Worker-Dir&#x27;) + &#x27; &amp;copy; Base on &#x27; + el(&#x27;a&#x27;,[&#x27;class=&quot;ui label&quot;&#x27;],el(&#x27;i&#x27;,[&#x27;class=&quot;balance scale icon&quot;&#x27;],&quot;&quot;) + &#x27;MIT License&#x27;)));  return renderHeader() + renderMain() + footer;&#125;function renderHeader()&#123;  const item = (template,name) =&gt; el(&#x27;a&#x27;,[&#x27;class=&quot;item&quot;&#x27;,`data-url=&quot;$&#123;template&#125;&quot;`],name);  var nav = el(&#x27;div&#x27;,[&#x27;class=&quot;ui large secondary inverted menu&quot;&#x27;],el(&#x27;div&#x27;,[&#x27;class=&quot;item&quot;&#x27;],el(&#x27;p&#x27;,[&#x27;id=&quot;hitokoto&quot;&#x27;],&#x27;条条大路通罗马&#x27;)))  var title = el(&#x27;h1&#x27;,[&#x27;class=&quot;ui inverted header&quot;&#x27;],el(&#x27;i&#x27;,[`class=&quot;$&#123;config.logo_icon&#125; icon&quot;`],&quot;&quot;) + el(&#x27;div&#x27;,[&#x27;class=&quot;content&quot;&#x27;],config.title + el(&#x27;div&#x27;,[&#x27;class=&quot;sub header&quot;&#x27;],config.subtitle)));  var menu = el(&#x27;div&#x27;,[&#x27;id=&quot;sengine&quot;&#x27;,&#x27;class=&quot;ui bottom attached tabular inverted secondary menu&quot;&#x27;],el(&#x27;div&#x27;,[&#x27;class=&quot;header item&quot;&#x27;],&#x27;&amp;nbsp;&#x27;) + config.search_engine.map((link,key) =&gt;&#123;    if(key == 0)&#123;      return el(&#x27;a&#x27;,[&#x27;class=&quot;active item&quot;&#x27;,`data-url=&quot;$&#123;link.template&#125;&quot;`],link.name);    &#125;else&#123;      return item(link.template,link.name);    &#125;  &#125;).join(&quot;&quot;))  var input = el(&#x27;div&#x27;,[&#x27;class=&quot;ui left corner labeled right icon fluid large input&quot;&#x27;],el(&#x27;div&#x27;,[&#x27;class=&quot;ui left corner label&quot;&#x27;],el(&#x27;img&#x27;,[&#x27;id=&quot;search-fav&quot;&#x27;,&#x27;class=&quot;left floated avatar ui image&quot;&#x27;,&#x27;src=&quot;https://www.baidu.com/favicon.ico&quot;&#x27;],&quot;&quot;)) + el(&#x27;input&#x27;,[&#x27;id=&quot;searchinput&quot;&#x27;,&#x27;type=&quot;search&quot;&#x27;,&#x27;placeholder=&quot;搜索你想要知道的……&quot;&#x27;,&#x27;autocomplete=&quot;off&quot;&#x27;],&quot;&quot;) + el(&#x27;i&#x27;,[&#x27;class=&quot;inverted circular search link icon&quot;&#x27;],&quot;&quot;));  return el(&#x27;header&#x27;,[],el(&#x27;div&#x27;,[&#x27;id=&quot;head&quot;&#x27;,&#x27;class=&quot;ui inverted vertical masthead center aligned segment&quot;&#x27;],(config.hitokoto ? el(&#x27;div&#x27;,[&#x27;id=&quot;nav&quot;&#x27;,&#x27;class=&quot;ui container&quot;&#x27;],nav) : &quot;&quot;) + el(&#x27;div&#x27;,[&#x27;id=&quot;title&quot;&#x27;,&#x27;class=&quot;ui text container&quot;&#x27;],title + (config.search ? input + menu :&quot;&quot;) + `$&#123;config.selling_ads ? &#x27;&lt;div&gt;&lt;a id=&quot;menubtn&quot; class=&quot;red ui icon inverted button&quot;&gt;&lt;i class=&quot;heart icon&quot;&gt;&lt;/i&gt; 喜欢此域名 &lt;/a&gt;&lt;/div&gt;&#x27; : &#x27;&#x27;&#125;`)))&#125;function renderMain() &#123;  var main = config.lists.map((item) =&gt; &#123;    const card = (url,name,desc)=&gt; el(&#x27;a&#x27;,[&#x27;class=&quot;card&quot;&#x27;,`href=$&#123;url&#125;`,&#x27;target=&quot;_blank&quot;&#x27;],el(&#x27;div&#x27;,[&#x27;class=&quot;content&quot;&#x27;],el(&#x27;img&#x27;,[&#x27;class=&quot;left floated avatar ui image&quot;&#x27;,`src=$&#123;getFavicon(url)&#125;`],&quot;&quot;) + el(&#x27;div&#x27;,[&#x27;class=&quot;header&quot;&#x27;],name) + el(&#x27;div&#x27;,[&#x27;class=&quot;meta&quot;&#x27;],desc)));    const divider = el(&#x27;h4&#x27;,[&#x27;class=&quot;ui horizontal divider header&quot;&#x27;],el(&#x27;i&#x27;,[`class=&quot;$&#123;item.icon&#125; icon&quot;`],&quot;&quot;)+item.name);    var content = el(&#x27;div&#x27;,[&#x27;class=&quot;ui four stackable cards&quot;&#x27;],item.list.map((link) =&gt;&#123;      return card(link.url,link.name,link.desc);    &#125;).join(&quot;&quot;));    return el(&#x27;div&#x27;,[&#x27;class=&quot;ui basic segment&quot;&#x27;],divider + content);  &#125;).join(&quot;&quot;);    return el(&#x27;main&#x27;,[],el(&#x27;div&#x27;,[&#x27;class=&quot;ui container&quot;&#x27;],main));&#125;function renderSeller() &#123;  const item = (type,content) =&gt; el(&#x27;div&#x27;,[&#x27;class=&quot;item&quot;&#x27;],el(&#x27;i&#x27;,[`class=&quot;$&#123;type&#125; icon&quot;`],&quot;&quot;) + el(&#x27;div&#x27;,[&#x27;class=&quot;content&quot;&#x27;],content));  var title = el(&#x27;h1&#x27;,[&#x27;class=&quot;ui yellow dividing header&quot;&#x27;],el(&#x27;i&#x27;,[&#x27;class=&quot;gem outline icon&quot;&#x27;],&quot;&quot;) + el(&#x27;div&#x27;,[&#x27;class=&quot;content&quot;&#x27;],config.sell_info.domain + &#x27; 正在出售&#x27;));  var action = el(&#x27;div&#x27;,[&#x27;class=&quot;actions&quot;&#x27;],el(&#x27;div&#x27;,[&#x27;class=&quot;ui basic cancel inverted button&quot;&#x27;],el(&#x27;i&#x27;,[&#x27;class=&quot;reply icon&quot;&#x27;],&quot;&quot;) + &#x27;返回&#x27;));  var contact = config.sell_info.contact.map((list) =&gt; &#123;    return item(list.type,list.content);  &#125;).join(&quot;&quot;);  var column = el(&#x27;div&#x27;,[&#x27;class=&quot;column&quot;&#x27;],el(&#x27;h3&#x27;,[&#x27;class=&quot;ui center aligned icon inverted header&quot;&#x27;],el(&#x27;i&#x27;,[&#x27;class=&quot;circular envelope open outline grey inverted icon&quot;&#x27;],&quot;&quot;) + &#x27;联系我&#x27;) + el(&#x27;div&#x27;,[&#x27;class=&quot;ui relaxed celled large list&quot;&#x27;],contact));  var price = el(&#x27;div&#x27;,[&#x27;class=&quot;column&quot;&#x27;],el(&#x27;div&#x27;,[&#x27;class=&quot;ui large yellow statistic&quot;&#x27;],el(&#x27;div&#x27;,[&#x27;class=&quot;value&quot;&#x27;],el(&#x27;i&#x27;,[`class=&quot;$&#123;config.sell_info.mon_unit&#125; icon&quot;`],&quot;&quot;) + config.sell_info.price)));  var content = el(&#x27;div&#x27;,[&#x27;class=&quot;content&quot;&#x27;],el(&#x27;div&#x27;,[&#x27;class=&quot;ui basic segment&quot;&#x27;],el(&#x27;div&#x27;,[&#x27;class=&quot;ui two column stackable center aligned grid&quot;&#x27;],el(&#x27;div&#x27;,[&#x27;class=&quot;ui inverted vertical divider&quot;&#x27;],&#x27;感兴趣？&#x27;) + el(&#x27;div&#x27;,[&#x27;class=&quot;middle aligned row&quot;&#x27;],price + column))));  return el(&#x27;div&#x27;,[&#x27;id=&quot;seller&quot;&#x27;,&#x27;class=&quot;ui basic modal&quot;&#x27;],title + content + action);&#125;function renderHTML(index,seller) &#123;  return `&lt;!DOCTYPE html&gt;  &lt;html lang=&quot;en&quot;&gt;  &lt;head&gt;      &lt;meta charset=&quot;UTF-8&quot;&gt;      &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1.0&quot;&gt;      &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;ie=edge&quot;&gt;      &lt;title&gt;$&#123;config.title&#125; - $&#123;config.subtitle&#125;&lt;/title&gt;      &lt;link href=&quot;https://cdn.jsdelivr.net/npm/semantic-ui-css@2.4.1/semantic.min.css&quot; rel=&quot;stylesheet&quot;&gt;      &lt;link href=&quot;https://cdn.jsdelivr.net/gh/sleepwood/cf-worker-dir@0.1.1/style.css&quot; rel=&quot;stylesheet&quot;&gt;      &lt;script src=&quot;https://cdn.jsdelivr.net/npm/jquery@3.4.1/dist/jquery.min.js&quot;&gt;&lt;/script&gt;      &lt;script src=&quot;https://cdn.jsdelivr.net/npm/semantic-ui-css@2.4.1/semantic.min.js&quot;&gt;&lt;/script&gt;  &lt;/head&gt;  &lt;body&gt;    $&#123;index&#125;    $&#123;config.selling_ads ? seller : &#x27;&#x27;&#125;    &lt;script src=&quot;https://v1.hitokoto.cn/?encode=js&amp;select=%23hitokoto&quot; defer&gt;&lt;/script&gt;    &lt;script&gt;      $(&#x27;#sengine a&#x27;).on(&#x27;click&#x27;, function (e) &#123;        $(&#x27;#sengine a.active&#x27;).toggleClass(&#x27;active&#x27;);        $(e.target).toggleClass(&#x27;active&#x27;);        $(&#x27;#search-fav&#x27;).attr(&#x27;src&#x27;,$(e.target).data(&#x27;url&#x27;).match(`+/https&#123;0,1&#125;:\/\/\S+\//+`)[0] + &#x27;/favicon.ico&#x27;) ;      &#125;);      $(&#x27;.search&#x27;).on(&#x27;click&#x27;, function (e) &#123;          var url = $(&#x27;#sengine a.active&#x27;).data(&#x27;url&#x27;);          url = url.replace(`+/\$s/+`,$(&#x27;#searchinput&#x27;).val());          window.open(url);      &#125;);      /* 鼠标聚焦时，回车事件 */      $(&quot;#searchinput&quot;).bind(&quot;keypress&quot;, function()&#123;          if (event.keyCode == 13)&#123;          // 触发需要调用的方法          $(&quot;.search&quot;).click();          &#125;      &#125;);      $(&#x27;#menubtn&#x27;).on(&#x27;click&#x27;, function (e) &#123;          $(&#x27;#seller&#x27;).modal(&#x27;show&#x27;);      &#125;);    &lt;/script&gt;  &lt;/body&gt;  &lt;/html&gt;`&#125;
复制进去之后，就可以随意更改list，来达到个人导航站的效果了。

今天是清明节假期，昨晚22:50上床，一觉睡到上午10:30左右（学生党是这样的） 上午给老mac换了硅脂，清了灰，然后决定休息会。 吃完饭翻了翻immmmm.com，翻到了一篇文章： 利用 Gemini Pro 为文章添加摘要 再一看，发现Google的Gemini Pro的api调用居然是免费的！For free！！！ 我很少很少能见到这么高质量的LLM的api免费，于是顿时起了兴趣，火速开始折腾。（踩了巨他妈多！！！！的！！！！坑！！！！！！！！）
按照原文。 第一步 获取 Gemini Pro 的 API 密钥：略
《略》………………… 打开bing搜索，启动小魔法，进入google，一分钟顺利搞定，拿到一个api key 第二步 Netlify 部署 API proxy解决部分地区不可用问题。项目地址：https://github.com/antergone/palm-netlify-proxy 部署之后复制链接，如：https://lucky-beignet-12345.netlify.app
easy，过。 第三步 改为 OpenAI 接口格式，项目地址：https://github.com/zuisong/gemini-openai-proxy 打开 main_cloudflare-workers.mjs 并复制代码到 Cloudflare Workers 中。（当然，也可以其他平台。但，只有 CF 方便手动修改） 修改以下 3 处地方： [可选] 自用设置，第 24 行，添加上自己的主域名，：origin: “https://immmmm.com“,第 1419 行，改为 Netlify 网址：var BASE_URL &#x3D; “https://lucky-beignet-12345.netlify.app“第 2106 行，写上 Gemini Pro 的 Key：const apiKey &#x3D; “YourGeminiProKey”;
