我发现了一个超级大宝贝儿————cloudflare它慷慨的为我们提供了许多免费的服务，其中就有制作镜像站这一个。

因为本博客还没上线图片功能，所以…之后会上线的！我们先到cloudflare到官网：www.cloudflare.com注册一个账号。注册好了在左边栏里选workers，然后在下拉出的选项里选概述选好了吗？好了，我们来创建一个workerworker，我们直接选免费计划…cloudflare worker免费计划有一天十万次请求，这是什么概念？这意味着一般人用绰绰有余，约等于完全免费！然后我们在worker的概述上点击蓝色按钮：快速编辑！然后你会进到一个类似于代码编辑器的地方你将会看到页面被分割成了两半，我们能看到左半部分有代码，不用管它，把代码全部删掉，让左边栏空出来。接下来，我们复制以下的代码到左边栏里。（不会吧不会吧，还有人不知道点击一下代码块，代码块的右上角就会浮现出一个小小的一件复制按钮）
// 反代目标网站.const upstream = &#x27;google.com&#x27;// 反代目标网站的移动版.const upstream_mobile = &#x27;google.com&#x27;// 访问区域黑名单（按需设置）.const blocked_region = [&#x27;TK&#x27;]// IP地址黑名单（按需设置）.const blocked_ip_address = [&#x27;0.0.0.0&#x27;, &#x27;127.0.0.1&#x27;]// 路径替换.const replace_dict = &#123;&#x27;$upstream&#x27;: &#x27;$custom_domain&#x27;,&#x27;//archiveofourown.org&#x27;: &#x27;&#x27;&#125;addEventListener(&#x27;fetch&#x27;, event =&gt; &#123;event.respondWith(fetchAndApply(event.request));&#125;)async function fetchAndApply(request) &#123;const region = request.headers.get(&#x27;cf-ipcountry&#x27;).toUpperCase();const ip_address = request.headers.get(&#x27;cf-connecting-ip&#x27;);const user_agent = request.headers.get(&#x27;user-agent&#x27;);let response = null;let url = new URL(request.url);let url_host = url.host;if (url.protocol == &#x27;http:&#x27;) &#123;    url.protocol = &#x27;https:&#x27;    response = Response.redirect(url.href);    return response;&#125;if (await device_status(user_agent)) &#123;    var upstream_domain = upstream;&#125; else &#123;    var upstream_domain = upstream_mobile;&#125;url.host = upstream_domain;if (blocked_region.includes(region)) &#123;    response = new Response(&#x27;Access denied: WorkersProxy is not available in your region yet.&#x27;, &#123;        status: 403    &#125;);&#125; else if(blocked_ip_address.includes(ip_address))&#123;    response = new Response(&#x27;Access denied: Your IP address is blocked by WorkersProxy.&#x27;, &#123;        status: 403    &#125;);&#125; else&#123;    let method = request.method;    let request_headers = request.headers;    let new_request_headers = new Headers(request_headers);    new_request_headers.set(&#x27;Host&#x27;, upstream_domain);    new_request_headers.set(&#x27;Referer&#x27;, url.href);    let original_response = await fetch(url.href, &#123;        method: method,        headers: new_request_headers    &#125;)    let original_response_clone = original_response.clone();    let original_text = null;    let response_headers = original_response.headers;    let new_response_headers = new Headers(response_headers);    let status = original_response.status;    new_response_headers.set(&#x27;cache-control&#x27; ,&#x27;public, max-age=14400&#x27;)    new_response_headers.set(&#x27;access-control-allow-origin&#x27;, &#x27;*&#x27;);    new_response_headers.set(&#x27;access-control-allow-credentials&#x27;, true);    new_response_headers.delete(&#x27;content-security-policy&#x27;);    new_response_headers.delete(&#x27;content-security-policy-report-only&#x27;);    new_response_headers.delete(&#x27;clear-site-data&#x27;);    const content_type = new_response_headers.get(&#x27;content-type&#x27;);    if (content_type.includes(&#x27;text/html&#x27;) &amp;&amp; content_type.includes(&#x27;UTF-8&#x27;)) &#123;        original_text = await replace_response_text(original_response_clone, upstream_domain, url_host);    &#125; else &#123;        original_text = original_response_clone.body    &#125;    response = new Response(original_text, &#123;        status,        headers: new_response_headers    &#125;)&#125;return response;&#125;async function replace_response_text(response, upstream_domain, host_name) &#123;let text = await response.text()var i, j;for (i in replace_dict) &#123;    j = replace_dict[i]    if (i == &#x27;$upstream&#x27;) &#123;        i = upstream_domain    &#125; else if (i == &#x27;$custom_domain&#x27;) &#123;        i = host_name    &#125;        if (j == &#x27;$upstream&#x27;) &#123;        j = upstream_domain    &#125; else if (j == &#x27;$custom_domain&#x27;) &#123;        j = host_name    &#125;    let re = new RegExp(i, &#x27;g&#x27;)    text = text.replace(re, j);&#125;return text;&#125;async function device_status (user_agent_info) &#123;var agents = [&quot;Android&quot;, &quot;iPhone&quot;, &quot;SymbianOS&quot;, &quot;Windows Phone&quot;, &quot;iPad&quot;, &quot;iPod&quot;];var flag = true;for (var v = 0; v &lt; agents.length; v++) &#123;    if (user_agent_info.indexOf(agents[v]) &gt; 0) &#123;        flag = false;        break;    &#125;&#125;return flag;&#125;
其中：const upstream &#x3D; ‘反代目标网站’const upstream_mobile &#x3D; ‘反代目标网站的移动版’const blocked_region &#x3D; 访问区域黑名单（按需设置）const blocked_ip_address &#x3D; [‘IP地址黑名单（按需设置）’, ‘127.0.0.1’]

