本站诞生时间扒的，emm，我看到里面还有消耗内存统计的代码，动态博客才能生效…一并放在这里了
&lt;!--耗时及占用内存开始--&gt;&lt;span id=&quot;momk&quot;&gt;&lt;/span&gt;&lt;span id=&quot;momk&quot; style=&quot;color: #ff0000;&quot;&gt;&lt;/span&gt;&lt;script type=&quot;text/javascript&quot;&gt;function NewDate(str) &#123;str = str.split(&#x27;-&#x27;);var date = new Date();date.setUTCFullYear(str[0], str[1] - 1, str[2]);date.setUTCHours(0, 0, 0, 0);return date;&#125;function momxc() &#123;&lt;!--这里要改成自己博客的诞生时间--&gt;var birthDay =NewDate(&quot;2022-04-20&quot;);var today=new Date();var timeold=today.getTime()-birthDay.getTime();var sectimeold=timeold/1000var secondsold=Math.floor(sectimeold);var msPerDay=24*60*60*1000; var e_daysold=timeold/msPerDay;var daysold=Math.floor(e_daysold);var e_hrsold=(daysold-e_daysold)*-24;var hrsold=Math.floor(e_hrsold);var e_minsold=(hrsold-e_hrsold)*-60;var minsold=Math.floor((hrsold-e_hrsold)*-60); var seconds=Math.floor((minsold-e_minsold)*-60).toString();document.getElementById(&quot;momk&quot;).innerHTML = &quot;这个小站已经在互联网上飘荡了&quot;+daysold+&quot;天&quot;+hrsold+&quot;小时&quot;+minsold+&quot;分&quot;+seconds+&quot;秒&quot;+&quot;，真是太不容易了&lt;br&gt;&quot;;setTimeout(momxc, 1000);&#125;momxc();&lt;/script&gt;&lt;style&gt;#momk&#123;animation:change 10s infinite;font-weight:800; &#125;@keyframes change&#123;0%&#123;color:#5cb85c;&#125;25%&#123;color:#556bd8;&#125;50%&#123;color:#e40707;&#125;75%&#123;color:#66e616;&#125;100% &#123;color:#67bd31;&#125;&#125;&lt;/style&gt;&lt;?php printf(&#x27; | 耗时 %.3f 秒 | 查询 %d 次 | 内存 %.2f MB |&#x27;,timer_stop( 0, 3 ),get_num_queries(),memory_get_peak_usage() / 1024 / 1024);?&gt;&lt;br&gt;&lt;!--耗时及占用内存结束--&gt;

